    elseif(isset($_POST['edit_times'])||isset($_POST['go_live'])) {
        $timingPolicy=$_POST['timing_policy']??'reject';
        if($timingPolicy==='shift'&&($_POST['approve_time_shift']??'')!=='1')throw new RuntimeException('Approve moving affected pending sessions and closing time before using this shift policy.');
        $notice=saveSessionSlot((int)$_POST['id'],$_POST['start_time']??'',$_POST['end_time']??'',(int)$_POST['revision'],'dashboard (open access)',$timingPolicy,isset($_POST['go_live']),$_POST['timing_topic']??null);
    }
    elseif(isset($_POST['notice_action'])) {$notice=editNotice((int)$_POST['notice_id'],$_POST['message']??'',$_POST['notice_action']==='remove',(int)$_POST['notice_revision'],'dashboard (open access)');}
    elseif(isset($_POST['notice_text'])) {$notice=publishNotice($_POST['notice_text'],'dashboard (open access)',isset($_POST['send_sms']));}
    elseif(isset($_POST['ai_question'])) {
        if(time()-($_SESSION['last_ai']??0)<15) throw new RuntimeException('Please wait 15 seconds between questions.');
        $_SESSION['last_ai']=time();$advice=aiAdvice($_POST['ai_question']);
