        if($cmd==='EXTEND') {if(($_POST['approved']??'')!=='1')throw new RuntimeException('Review and approve the revised timings first.');$cmd.=' '.(int)($_POST['minutes']??0);}
        $notice=command($cmd,'dashboard (open access)',$id,$policy,$rev);
    }
}catch(Throwable $e){$error=$e->getMessage();}
