ry>Edit times</summary><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="revision" value="<?=$r['revision']?>"><label>Start (EAT)<input type="time" name="start_time" value="<?=date('H:i',$r['start'])?>" required></label><label>End (EAT)<input type="time" name="end_time" value="<?=date('H:i',$r['end'])?>" required></label><label class="approval"><input type="checkbox" class="keep-duration" checked> Keep duration when changing start</label><label>Live topic (optional)<input name="timing_topic" maxlength="200" value="<?=h(liveTopic($r['id']))?>" placeholder="For example, Design Thinking"></label><label>Adjust other sessions<select name="timing_policy"><option value="reject">Keep others fixed; reject overlaps</option><option value="protect">Shift pending; protect breaks and closing</option><option value="shift">Shift affected pending, including closing</option></select></label><label class="approval"><input type="checkbox" name="approve_time_shift" value="1"> I approve moving affected sessions, breaks and closing if needed</label><button name="edit_times" value="1">Save times</button><?php if(!in_array($r['status'],['completed','skipped'],true)):?> <button name="go_live" value="1">Save and go live</button><?php endif?><small>For a live session, start edits also correct its displayed actual start. Go live ends the break and completes the previous active session.</small></form></details></td><?php endif?></tr><?php endforeach?></tbody></table></div></section>
